#!/usr/bin/env python3
"""CSV Insights - a dependency-free command-line analytics tool."""

import csv
import sys
import json
import argparse
from decimal import Decimal, InvalidOperation


def parse_where(token):
    """Parse a COLUMN=VALUE filter token into (column, value)."""
    if "=" not in token:
        raise ValueError(f"malformed filter '{token}': expected COLUMN=VALUE")
    column, _, value = token.partition("=")
    if column == "":
        raise ValueError(f"malformed filter '{token}': empty column name")
    return column, value


def read_csv(path):
    """Read a CSV file and return (headers, rows).

    Rows with the wrong number of fields raise a ValueError.
    """
    try:
        with open(path, "r", newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            try:
                headers = next(reader)
            except StopIteration:
                raise ValueError("input file is empty")
            if any(h == "" for h in headers):
                raise ValueError("headers must be non-empty")
            if len(set(headers)) != len(headers):
                raise ValueError("headers must be unique")
            rows = []
            for i, row in enumerate(reader, start=2):
                if len(row) != len(headers):
                    raise ValueError(
                        f"row {i} has {len(row)} fields, expected {len(headers)}"
                    )
                rows.append(row)
            return headers, rows
    except FileNotFoundError:
        raise ValueError(f"input file not found: {path}")
    except OSError as exc:
        raise ValueError(f"could not read input file: {exc}")


def apply_filters(headers, rows, filters):
    """Return rows that match all (column, value) filters exactly."""
    if not filters:
        return rows
    col_indices = []
    for column, value in filters:
        if column not in headers:
            raise ValueError(f"unknown column '{column}' in --where filter")
        col_indices.append((headers.index(column), value))
    out = []
    for row in rows:
        if all(row[idx] == value for idx, value in col_indices):
            out.append(row)
    return out


def to_decimal(value, row_num, column):
    """Convert a string to Decimal, raising on blank/invalid."""
    if value == "":
        raise ValueError(
            f"blank numeric value in column '{column}' at row {row_num}"
        )
    try:
        return Decimal(value)
    except InvalidOperation:
        raise ValueError(
            f"invalid numeric value '{value}' in column '{column}' at row {row_num}"
        )


def aggregate(headers, rows, group_by, sum_cols, avg_cols):
    """Group rows and compute sums/averages using Decimal."""
    if group_by not in headers:
        raise ValueError(f"unknown column '{group_by}' in --group-by")
    group_idx = headers.index(group_by)

    sum_indices = []
    for col in sum_cols:
        if col not in headers:
            raise ValueError(f"unknown column '{col}' in --sum")
        sum_indices.append((col, headers.index(col)))

    avg_indices = []
    for col in avg_cols:
        if col not in headers:
            raise ValueError(f"unknown column '{col}' in --avg")
        avg_indices.append((col, headers.index(col)))

    groups = {}
    for i, row in enumerate(rows, start=2):
        key = row[group_idx]
        if key not in groups:
            groups[key] = {"count": 0, "sums": {}, "avgs": {}}
            for col, _ in sum_indices:
                groups[key]["sums"][col] = Decimal(0)
            for col, _ in avg_indices:
                groups[key]["avgs"][col] = Decimal(0)
        groups[key]["count"] += 1
        for col, idx in sum_indices:
            groups[key]["sums"][col] += to_decimal(row[idx], i, col)
        for col, idx in avg_indices:
            groups[key]["avgs"][col] += to_decimal(row[idx], i, col)

    out_cols = [group_by]
    for col in sum_cols:
        out_cols.append(f"sum_{col}")
    for col in avg_cols:
        out_cols.append(f"avg_{col}")

    out_rows = []
    for key in sorted(groups.keys()):
        g = groups[key]
        record = {group_by: key}
        for col in sum_cols:
            record[f"sum_{col}"] = format_decimal(g["sums"][col])
        for col in avg_cols:
            total = g["avgs"][col]
            avg = total / Decimal(g["count"])
            record[f"avg_{col}"] = format_decimal(avg)
        out_rows.append(record)
    return out_cols, out_rows


def format_decimal(value):
    """Format a Decimal as a plain, minimal decimal string."""
    if value == value.to_integral_value():
        return str(int(value))
    normalized = value.normalize()
    text = format(normalized, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    if text == "" or text == "-0":
        text = "0"
    return text


def emit_json(out_cols, out_rows):
    """Emit rows as a JSON array of objects."""
    if isinstance(out_rows, list) and out_rows and isinstance(out_rows[0], dict):
        sys.stdout.write(json.dumps(out_rows, indent=2))
        sys.stdout.write("\n")
        return
    records = []
    for row in out_rows:
        records.append(dict(zip(out_cols, row)))
    sys.stdout.write(json.dumps(records, indent=2))
    sys.stdout.write("\n")


def emit_csv(out_cols, out_rows):
    """Emit rows as RFC-compliant CSV with a header."""
    writer = csv.writer(sys.stdout)
    writer.writerow(out_cols)
    for row in out_rows:
        if isinstance(row, dict):
            writer.writerow([row[c] for c in out_cols])
        else:
            writer.writerow(row)


def build_parser():
    parser = argparse.ArgumentParser(
        prog="csv-insights",
        description="Dependency-free CSV analytics tool.",
    )
    parser.add_argument("input", help="input CSV file path")
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        type=parse_where,
        help="filter as COLUMN=VALUE (repeatable, AND-combined)",
    )
    parser.add_argument("--group-by", dest="group_by", default=None, help="group column")
    parser.add_argument("--sum", action="append", default=[], help="sum column")
    parser.add_argument("--avg", action="append", default=[], help="average column")
    parser.add_argument(
        "--output",
        choices=["json", "csv"],
        default="json",
        help="output format (default: json)",
    )
    return parser


def main(argv=None):
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except argparse.ArgumentError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 2
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2

    try:
        headers, rows = read_csv(args.input)
        rows = apply_filters(headers, rows, args.where)

        if args.sum or args.avg:
            if not args.group_by:
                raise ValueError("--sum and --avg require --group-by")
            out_cols, out_rows = aggregate(
                headers, rows, args.group_by, args.sum, args.avg
            )
        else:
            if args.group_by:
                raise ValueError("--group-by requires --sum or --avg")
            out_cols = headers
            out_rows = rows

        if args.output == "json":
            emit_json(out_cols, out_rows)
        else:
            emit_csv(out_cols, out_rows)
        return 0
    except ValueError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 1
    except BrokenPipeError:
        return 0


if __name__ == "__main__":
    sys.exit(main())
